/**
 * Environment briefs: derived facts about a machine and a workspace.
 *
 * Briefs are a cache, not the source of truth. They are generated by read-only
 * probes, refreshed on a TTL or a workspace fingerprint change, and preserved
 * when the host is unreachable.
 *
 * Content rule: only facts that stay true across sessions, and never a fragment
 * of prose. A truncated sentence can invert its meaning, so prose is included
 * only as whole sentences; everything else is structured (repos, stacks, roles).
 */
import { createHash } from 'node:crypto'
import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs'
import { dirname, join, posix } from 'node:path'
import { attrsType, attrsVersion, sftpCall, shellQuote, slugFor } from '../util.js'

const MACHINE_TTL_MS = 24 * 60 * 60 * 1000
const BRIEF_VERSION = 3
const MAX_REPOS = 12
const README_SENTENCE_LIMIT = 140

const WORKSPACE_FILES = ['.git/HEAD', 'package.json', 'pyproject.toml', 'Makefile', 'docker-compose.yml', '.nvmrc', 'README.md']

const MANIFEST_FILES = [
  'package.json',
  'pyproject.toml',
  'requirements.txt',
  'go.mod',
  'Cargo.toml',
  'pubspec.yaml',
  'pom.xml',
  'build.gradle',
  'composer.json',
  'Makefile',
  'README.md',
  'AGENTS.md',
]

export class MemoryBrief {
  constructor({ dataDir, hostFor, routing, settings, connectHost, now = () => Date.now() }) {
    this.root = join(dataDir, 'brief')
    this.hostFor = hostFor
    this.routing = routing
    this.settings = settings
    this.connectHost = connectHost
    this.now = now
    this.machineCache = new Map()
    this.workspaceCache = new Map()
    this.pending = new Map()
  }

  machineFile(connectionId) {
    return join(this.root, 'machines', `${safe(connectionId)}.json`)
  }

  workspaceFile(connectionId, remotePath) {
    return join(this.root, 'workspaces', safe(connectionId), `${slugFor(remotePath)}.json`)
  }

  machine(connectionId) {
    const key = `machine:${connectionId}`
    if (this.machineCache.has(key)) return this.machineCache.get(key)
    const doc = readJson(this.machineFile(connectionId))
    const value = doc && doc.data ? doc : null
    this.machineCache.set(key, value)
    return value
  }

  workspace(connectionId, remotePath) {
    const key = `workspace:${connectionId}:${remotePath}`
    if (this.workspaceCache.has(key)) return this.workspaceCache.get(key)
    const doc = readJson(this.workspaceFile(connectionId, remotePath))
    const value = doc && doc.data ? doc : null
    this.workspaceCache.set(key, value)
    return value
  }

  saveMachine(connectionId, data) {
    const doc = { version: BRIEF_VERSION, connectionId, generatedAt: new Date(this.now()).toISOString(), data }
    writeAtomic(this.machineFile(connectionId), doc)
    this.machineCache.set(`machine:${connectionId}`, doc)
    return doc
  }

  saveWorkspace(connectionId, remotePath, data, fingerprint) {
    const doc = {
      version: BRIEF_VERSION,
      connectionId,
      remotePath,
      generatedAt: new Date(this.now()).toISOString(),
      fingerprint,
      data,
    }
    writeAtomic(this.workspaceFile(connectionId, remotePath), doc)
    this.workspaceCache.set(`workspace:${connectionId}:${remotePath}`, doc)
    return doc
  }

  isFresh(doc) {
    if (!doc || doc.version !== BRIEF_VERSION || typeof doc.generatedAt !== 'string') return false
    const age = this.now() - Date.parse(doc.generatedAt)
    const ttl = Math.max(1, this.settings.get().probeTtlHours || 24) * 60 * 60 * 1000
    return Number.isFinite(age) && age >= 0 && age < Math.min(ttl, MACHINE_TTL_MS)
  }

  async refresh(connectionId, remotePath, { force = false } = {}) {
    const key = `refresh:${connectionId}:${remotePath || ''}`
    if (this.pending.has(key)) return this.pending.get(key)
    const task = this.#refresh(connectionId, remotePath, force).finally(() => this.pending.delete(key))
    this.pending.set(key, task)
    return task
  }

  async #refresh(connectionId, remotePath, force) {
    const host = await this.connectHost(connectionId)
    if (!host) throw new Error('connection not found')
    const machine = this.machine(connectionId)
    if ((force || !this.isFresh(machine)) && this.settings.get().machineProbe !== false) {
      try {
        const data = await probeMachine(host)
        this.saveMachine(connectionId, data)
      } catch {
        /* keep the previous brief; the UI marks it as not refreshed */
      }
    }
    if (typeof remotePath === 'string' && remotePath.length > 0 && this.settings.get().workspaceScan !== false) {
      try {
        const fingerprint = await workspaceFingerprint(host, remotePath)
        const current = this.workspace(connectionId, remotePath)
        if (force || !this.isFresh(current) || current.fingerprint !== fingerprint) {
          const data = await scanWorkspace(host, this.routing, remotePath)
          this.saveWorkspace(connectionId, remotePath, data, fingerprint)
        }
      } catch {
        /* keep the previous workspace brief */
      }
    }
    return { machine: this.machine(connectionId), workspace: this.workspace(connectionId, remotePath) }
  }
}

// ---------------------------------------------------------------- machine

async function probeMachine(host) {
  const command = [
    'printf "osname=%s\\n" "$(. /etc/os-release 2>/dev/null; printf "%s" "$PRETTY_NAME")"',
    'printf "kernel=%s\\n" "$(uname -r 2>/dev/null)"',
    'printf "arch=%s\\n" "$(uname -m 2>/dev/null)"',
    'printf "shell=%s\\n" "${SHELL:-}"',
    'printf "cpu=%s\\n" "$(nproc 2>/dev/null || getconf _NPROCESSORS_ONLN 2>/dev/null || echo ?)"',
    'awk \'/MemTotal/{printf "mem_kb=%d\\n", $2}\' /proc/meminfo 2>/dev/null || true',
    'for c in node python3 docker git; do ' +
      'case "$c" in ' +
      'node) v=$(node -v 2>/dev/null);; ' +
      'python3) v=$(python3 -V 2>&1);; ' +
      'docker) v=$(docker --version 2>/dev/null);; ' +
      'git) v=$(git --version 2>/dev/null);; ' +
      'esac; ' +
      '[ -n "$v" ] && printf "tool=%s\\t%s\\n" "$c" "$v"; ' +
      'done',
  ].join('; ')
  const result = await host.runCommand(command, null, { maxBytes: 64 * 1024, timeoutMs: 10000 })
  const parsed = parseKeyValues(result.stdout)
  const tools = []
  for (const line of result.stdout.split('\n')) {
    const match = /^tool=([^\t]+)\t(.+)$/.exec(line.trim())
    if (match) tools.push(formatToolVersion(match[1], match[2]))
  }
  const cpu = parsed.cpu && parsed.cpu !== '?' ? `${parsed.cpu} 核` : ''
  const memGb = parsed.mem_kb ? Math.round(Number(parsed.mem_kb) / 1024 / 1024) : 0
  return {
    os: [parsed.osname, parsed.kernel ? `Linux ${parsed.kernel}` : '', parsed.arch].filter(Boolean).join(' · '),
    shell: parsed.shell || '',
    resources: [cpu, memGb > 0 ? `${memGb} GB` : ''].filter(Boolean).join(' · '),
    tools,
  }
}

function formatToolVersion(name, raw) {
  const text = String(raw || '').trim()
  let version = ''
  if (name === 'node') version = (/v?(\d+(?:\.\d+){0,1})/.exec(text) || [])[1] || ''
  else if (name === 'python3') version = (/Python\s+(\d+\.\d+)/.exec(text) || [])[1] || ''
  else if (name === 'docker') version = (/version\s+(\d+\.\d+)/i.exec(text) || [])[1] || ''
  else if (name === 'git') version = (/version\s+(\d+\.\d+)/i.exec(text) || [])[1] || ''
  return version ? `${name} ${version}` : name
}

// ---------------------------------------------------------------- workspace

async function workspaceFingerprint(host, remotePath) {
  const sftp = host.requireSftp()
  const data = []
  for (const name of WORKSPACE_FILES) {
    const target = posix.join(remotePath, name)
    try {
      const attrs = await sftpCall(sftp, 'stat', target)
      data.push(`${name}:${attrsVersion(attrs)}`)
    } catch {
      data.push(`${name}:absent`)
    }
  }
  const dirs = await listTopDirs(host, remotePath)
  data.push(`dirs:${dirs.sort().join(',')}`)
  return createHash('sha1').update(data.join('|')).digest('hex')
}

/**
 * One exec for every manifest under the workspace (depth 2). A multi-repo scan
 * should not need a stat per repo per language.
 * @returns {Promise<Map<string, Set<string>>>} repo folder ('' = workspace root) -> file names
 */
async function scanManifests(host, remotePath) {
  const map = new Map()
  const args = MANIFEST_FILES.map((name) => `-name ${name}`).join(' -o ')
  const command =
    'cd ' + shellQuote(remotePath) + ' 2>/dev/null && ' +
    `find . -maxdepth 2 \\( ${args} \\) -print 2>/dev/null | head -400`
  try {
    const result = await host.runCommand(command, null, { maxBytes: 64 * 1024, timeoutMs: 8000 })
    for (const raw of result.stdout.split('\n')) {
      const line = raw.trim().replace(/^\.\//, '')
      if (line.length === 0) continue
      const parts = line.split('/')
      if (parts.length > 2) continue
      const key = parts.length === 2 ? parts[0] : ''
      const name = parts[parts.length - 1]
      if (!map.has(key)) map.set(key, new Set())
      map.get(key).add(name)
    }
  } catch {
    /* no manifests is a valid scan result */
  }
  return map
}

/** Depth-2 markers for plain (non-git) directories: nested checkouts and docs. */
async function scanChildMarkers(host, remotePath) {
  const command =
    'cd ' + shellQuote(remotePath) + ' 2>/dev/null && ' +
    'find . -maxdepth 2 \\( -name .git -o -name .svn -o -name .hg ' +
    '-o -name README.md -o -name package.json -o -name pyproject.toml ' +
    '-o -name go.mod -o -name Cargo.toml -o -name Makefile \\) -print 2>/dev/null | head -160'
  const map = new Map()
  try {
    const result = await host.runCommand(command, null, { maxBytes: 32 * 1024, timeoutMs: 8000 })
    for (const raw of result.stdout.split('\n')) {
      const line = raw.trim().replace(/^\.\//, '')
      const index = line.lastIndexOf('/')
      if (index <= 0) continue
      const dir = line.slice(0, index)
      if (dir.includes('/')) continue
      if (!map.has(dir)) map.set(dir, new Set())
      map.get(dir).add(line.slice(index + 1))
    }
  } catch {
    /* markers are a bonus; the directory list still stands on its own */
  }
  return map
}

async function scanWorkspace(host, routing, remotePath) {
  const dirs = await listTopDirs(host, remotePath)
  const manifests = await scanManifests(host, remotePath)
  const rootManifests = manifests.get('') ?? new Set()

  const repos = []
  if (await isDirectory(host, posix.join(remotePath, '.git'))) repos.push({ name: '.', path: remotePath })
  for (const name of dirs.slice(0, 20)) {
    const dir = posix.join(remotePath, name)
    if (await isDirectory(host, posix.join(dir, '.git'))) repos.push({ name, path: dir })
  }

  const readmeText = await readOptional(routing, host, posix.join(remotePath, 'README.md'))
  const readme = readmeMeta(readmeText)
  const entryDocs = rootManifests.has('AGENTS.md') ? ['AGENTS.md'] : []

  if (repos.length === 0) {
    const markers = await scanChildMarkers(host, remotePath)
    const children = []
    for (const name of dirs.slice(0, 10)) {
      const found = markers.get(name)
      const stack = stackOf(manifests.get(name))
      if (found === undefined) {
        children.push({ name, vcs: '', stack })
        continue
      }
      const vcs = found.has('.git') ? 'git' : found.has('.svn') ? 'svn' : found.has('.hg') ? 'hg' : ''
      children.push({ name, vcs, stack })
    }
    const vcs = []
    if (await isDirectory(host, posix.join(remotePath, '.svn'))) vcs.push('svn')
    if (await isDirectory(host, posix.join(remotePath, '.hg'))) vcs.push('hg')
    let summary = readme.sentences
    if (summary === '') {
      for (const child of children) {
        const found = markers.get(child.name)
        if (found === undefined || !found.has('README.md')) continue
        const content = await readOptional(routing, host, posix.join(remotePath, child.name, 'README.md'))
        summary = readmeMeta(content).sentences
        if (summary !== '') break
      }
    }
    return {
      kind: 'plain',
      git: null,
      vcs: vcs.join(', '),
      dirs: dirs.slice(0, 10),
      children,
      stack: stackOf(rootManifests),
      commands: [],
      entryDocs,
      readme: summary,
    }
  }

  if (repos.length === 1) {
    const remotes = await readRemotes(host, repos)
    const repo = await scanRepo(host, routing, repos[0], remotes.get(repos[0].path) || '', manifests.get('') ?? new Set())
    return {
      kind: 'repo',
      git: repo.remote ? { remote: repo.remote } : null,
      stack: repo.stack,
      commands: repo.commands,
      entryDocs,
      readme: repo.readme || readme.sentences,
    }
  }

  const remotes = await readRemotes(host, repos.slice(0, MAX_REPOS))
  const scanned = []
  for (const repo of repos.slice(0, MAX_REPOS)) {
    const item = await scanRepo(host, routing, repo, remotes.get(repo.path) || '', manifests.get(repo.name) ?? new Set(), false)
    item.role = readme.roles.get(repo.name) || ''
    scanned.push(item)
  }
  return {
    kind: 'multi-repo',
    totalRepos: repos.length,
    git: null,
    repos: scanned,
    stack: '',
    commands: [],
    entryDocs,
    readme: '',
  }
}

async function scanRepo(host, routing, repo, remote, manifests, wantReadme = true) {
  const found = manifests instanceof Set ? manifests : new Set()
  const stack = stackOf(found)
  const commands = []
  const role = ''
  if (found.has('package.json')) {
    const packageText = await readOptional(routing, host, posix.join(repo.path, 'package.json'))
    try {
      const pkg = JSON.parse(packageText)
      const scripts = pkg && pkg.scripts && typeof pkg.scripts === 'object' ? Object.keys(pkg.scripts) : []
      for (const script of ['dev', 'build', 'test', 'lint', 'verify']) {
        if (scripts.includes(script)) commands.push(`npm run ${script}`)
      }
    } catch {
      /* keep the stack hint */
    }
  }
  const readme = wantReadme
    ? readmeMeta(await readOptional(routing, host, posix.join(repo.path, 'README.md')))
    : { sentences: '', roles: new Map() }
  return {
    name: repo.name,
    remote: remote || '',
    stack,
    commands: [...new Set(commands)],
    role,
    readme: readme.sentences,
  }
}

function stackOf(found) {
  if (!(found instanceof Set)) return ''
  const stack = []
  if (found.has('package.json')) stack.push('Node')
  if (found.has('pyproject.toml') || found.has('requirements.txt')) stack.push('Python')
  if (found.has('go.mod')) stack.push('Go')
  if (found.has('Cargo.toml')) stack.push('Rust')
  if (found.has('pubspec.yaml')) stack.push('Flutter')
  if (found.has('pom.xml') || found.has('build.gradle')) stack.push('Java')
  if (found.has('composer.json')) stack.push('PHP')
  if (found.has('Makefile')) stack.push('Make')
  return stack.join(' + ')
}

/**
 * README is reference prose, never injected as a fragment: keep the title and the
 * leading *complete* sentences, and drop anything that would be cut mid-sentence.
 * Table rows are read for repo roles instead of being flattened into prose.
 */
function readmeMeta(text) {
  const raw = String(text || '')
  if (raw.trim().length === 0) return { title: '', sentences: '', roles: new Map() }

  const titleMatch = /^#\s+(.+)$/m.exec(raw)
  const title = titleMatch ? cleanInline(titleMatch[1]).slice(0, 40) : ''

  const roles = new Map()
  for (const line of raw.split('\n')) {
    const cells = line.split('|').map((cell) => cell.trim())
    if (cells.length < 3) continue
    const link = /\[[^\]]*\]\(\.?\/?([^/)\s]+)\/?\)/.exec(cells[1] || '')
    if (!link) continue
    const role = cleanInline((cells[2] || '').replace(/\*\*/g, '')).slice(0, 16)
    if (role.length > 0 && !roles.has(link[1])) roles.set(link[1], role)
  }

  const prose = raw
    .replace(/```[\s\S]*?```/g, ' ')
    .split('\n')
    .filter((line) => !/^\s*[|#>\-*]/.test(line) && !/^\s*$/.test(line))
    .map((line) => cleanInline(line))
    .filter((line) => line.length > 0)
    .join(' ')

  const sentences = []
  let total = 0
  for (const sentence of prose.split(/(?<=[。！？!?])\s*/)) {
    const item = sentence.trim()
    if (item.length === 0) continue
    if (total + item.length > README_SENTENCE_LIMIT) break
    sentences.push(item)
    total += item.length
    if (sentences.length >= 2) break
  }
  return { title, sentences: sentences.join(' '), roles }
}

function cleanInline(value) {
  return String(value || '')
    .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
    .replace(/[`*_>#]/g, '')
    .replace(/\s+/g, ' ')
    .trim()
}

// ---------------------------------------------------------------- remote io

async function readRemotes(host, repos) {
  const remotes = new Map()
  if (repos.length === 0) return remotes
  const command = `for d in ${repos.map((repo) => shellQuote(repo.path)).join(' ')}; do printf '%s\\t' "$d"; git -C "$d" remote get-url origin 2>/dev/null; printf '\\n'; done`
  try {
    const result = await host.runCommand(command, null, { maxBytes: 32 * 1024, timeoutMs: 8000 })
    for (const line of result.stdout.split('\n')) {
      const index = line.indexOf('\t')
      if (index <= 0) continue
      const path = line.slice(0, index)
      const remote = line.slice(index + 1).trim()
      if (remote) remotes.set(path, remote)
    }
  } catch {
    /* remotes are optional */
  }
  return remotes
}

async function listTopDirs(host, remotePath) {
  try {
    const entries = await sftpCall(host.requireSftp(), 'readdir', remotePath)
    return entries
      .filter((entry) => entry.filename && !entry.filename.startsWith('.') && (!entry.attrs || entry.attrs.isDirectory?.() !== false))
      .map((entry) => entry.filename)
      .slice(0, 40)
  } catch {
    return []
  }
}

async function pathType(host, target) {
  try {
    const attrs = await sftpCall(host.requireSftp(), 'stat', target)
    return attrsType(attrs)
  } catch {
    return null
  }
}

async function isDirectory(host, target) {
  return (await pathType(host, target)) === 'directory'
}

async function readOptional(routing, host, path) {
  try {
    const text = await routing.readText(host, path)
    return text.slice(0, 4096)
  } catch {
    return ''
  }
}

function parseKeyValues(text) {
  const values = {}
  for (const line of String(text || '').split('\n')) {
    const index = line.indexOf('=')
    if (index <= 0) continue
    values[line.slice(0, index)] = line.slice(index + 1).trim()
  }
  return values
}

function safe(value) {
  return String(value || '').replace(/[^A-Za-z0-9._-]/g, '-').slice(0, 80) || 'unknown'
}

function writeAtomic(file, value) {
  mkdirSync(dirname(file), { recursive: true })
  const temp = `${file}.tmp-${process.pid}-${Math.random().toString(16).slice(2)}`
  writeFileSync(temp, `${JSON.stringify(value, null, 2)}\n`, { encoding: 'utf8', mode: 0o600 })
  renameSync(temp, file)
}

function readJson(file) {
  try {
    const text = readFileSync(file, 'utf8')
    return JSON.parse(text.charCodeAt(0) === 0xfeff ? text.slice(1) : text)
  } catch {
    return null
  }
}
